mapper.select:
select t.value_source as valueSource, t.curve_code as curveCode, t.remark as curveName, t.int_curve_type as intCurveType, 'CNY' as ccy, '线性插值' as interMethod, 'A/365' as dayRules, '银行间交易日历' as calender, '起息日向后' as interestDateRule, '按年复利' as interestCalMethod, '年付' as interestFreq/*, eff_status as effStatus*/ from MST_CURVE_DEF t
1=1
and t.curve_code = #{curveCode}
and t.curve_type = #{curve_type}
and t.int_curve_type = #{intCurveType}

select CURVE_CODE id,
/*CURVE_CODE || ':' || INT_CURVE_TYPE text,*/ remark text,
INT_CURVE_TYPE object from MST_CURVE_DEF
1=1
AND ( CURVE_CODE LIKE CONCAT('%', CONCAT(#{search}, '%')) OR INT_CURVE_TYPE LIKE CONCAT('%', CONCAT(#{search}, '%')) OR remark LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND curve_type = #{curve_type}

		select
		CURVE_CODE curveCode,
		remark curveName,
		INT_CURVE_TYPE as curveType
		from MST_CURVE_DEF

			1=1
-- 			 NVL(eff_status,'E') = #{effStatus,jdbcType=VARCHAR}

				and remark = #{curveName,jdbcType=VARCHAR}


				and t.curve_type = #{curve_type}
